// Loads the Rust core (crates/gs-client → ./wasm, generated by `pnpm build:wasm`).
// Every type below is generated from Rust — edit the Rust, not these.
import init, * as core from './wasm/gs_client.js';

export type { Command, Event, Hud, Input, Kind, NetStats, PlayerId, ScoreRow, TickEvent } from './wasm/gs_client.js';
export { Button, GameClient, LocalServer } from './wasm/gs_client.js';

export type Core = typeof core & { memory: WebAssembly.Memory };

let loading: Promise<Core> | null = null;

/** Initialise the wasm module once; every later call returns the same instance. */
export function loadCore(): Promise<Core> {
  loading ??= init().then((out) => ({ ...core, memory: out.memory }));
  return loading;
}
